function maxCopies(nums: number[], k: number): number {
  const a = [...nums].sort((x, y) => x - y);
  let best = 0;
  for (let r = 0; r < a.length; r++) {
    let cost = 0, l = r;
    while (l > 0 && cost + a[r] - a[l - 1] <= k) {
      cost += a[r] - a[l - 1];
      l--;
    }
    best = Math.max(best, r - l + 1);
  }
  return best;
}

